package com.termux.app.workspace;
import android.Manifest;import android.app.*;import android.os.Build;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.util.ReflectionHelpers;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class WorkspaceImageSaveAccessTest {
 Activity activity;WorkspaceImageSaveAccess access;int originalSdk;
 @Before public void setup(){activity=Robolectric.buildActivity(Activity.class).setup().get();access=new WorkspaceImageSaveAccess(activity);originalSdk=Build.VERSION.SDK_INT;Shadows.shadowOf(RuntimeEnvironment.application).denyPermissions(Manifest.permission.WRITE_EXTERNAL_STORAGE);}
 @After public void end(){access.close();ReflectionHelpers.setStaticField(Build.VERSION.class,"SDK_INT",originalSdk);activity.finish();}
 @Test public void modernSaveRequiresNeitherStoragePermissionNorAllFilesSettings(){for(int sdk:new int[]{29,30,33,35}){ReflectionHelpers.setStaticField(Build.VERSION.class,"SDK_INT",sdk);AtomicInteger ready=new AtomicInteger();assertTrue(access.request(ready::incrementAndGet,()->fail("No permission needed")));assertEquals(1,ready.get());assertNull(Shadows.shadowOf(activity).getLastRequestedPermission());assertNull(Shadows.shadowOf(activity).getNextStartedActivity());}}
 @Test public void legacyRequestsOnlyWriteAndDenialNeverOpensSettings(){for(int sdk:new int[]{26,28}){ReflectionHelpers.setStaticField(Build.VERSION.class,"SDK_INT",sdk);AtomicInteger ready=new AtomicInteger(),denied=new AtomicInteger();assertTrue(access.request(ready::incrementAndGet,denied::incrementAndGet));org.robolectric.shadows.ShadowActivity.PermissionsRequest request=Shadows.shadowOf(activity).getLastRequestedPermission();assertArrayEquals(new String[]{Manifest.permission.WRITE_EXTERNAL_STORAGE},request.requestedPermissions);assertEquals(WorkspaceImageSaveAccess.REQUEST,request.requestCode);android.content.Intent launched=Shadows.shadowOf(activity).getNextStartedActivity();if(launched!=null)assertEquals("android.content.pm.action.REQUEST_PERMISSIONS",launched.getAction());assertFalse(access.request(ready::incrementAndGet,denied::incrementAndGet));assertFalse(access.permissionResult(123));assertTrue(access.permissionResult(WorkspaceImageSaveAccess.REQUEST));assertEquals(0,ready.get());assertEquals(1,denied.get());assertNull(Shadows.shadowOf(activity).getNextStartedActivity());}}
 @Test public void legacyGrantAllowsRetryAndClosedContinuationNeverSaves(){AtomicInteger ready=new AtomicInteger(),denied=new AtomicInteger();access.request(ready::incrementAndGet,denied::incrementAndGet);Shadows.shadowOf(RuntimeEnvironment.application).grantPermissions(Manifest.permission.WRITE_EXTERNAL_STORAGE);access.permissionResult(WorkspaceImageSaveAccess.REQUEST);assertEquals(1,ready.get());assertTrue(access.request(ready::incrementAndGet,denied::incrementAndGet));assertEquals(2,ready.get());Shadows.shadowOf(RuntimeEnvironment.application).denyPermissions(Manifest.permission.WRITE_EXTERNAL_STORAGE);access.request(ready::incrementAndGet,denied::incrementAndGet);access.close();Shadows.shadowOf(RuntimeEnvironment.application).grantPermissions(Manifest.permission.WRITE_EXTERNAL_STORAGE);access.permissionResult(WorkspaceImageSaveAccess.REQUEST);assertEquals(2,ready.get());assertFalse(access.request(ready::incrementAndGet,denied::incrementAndGet));}
 @Test public void termuxPermissionRouteResumesOnlyItsGalleryContinuation(){com.termux.app.TermuxActivity owner=Robolectric.buildActivity(com.termux.app.TermuxActivity.class).get();AtomicInteger ready=new AtomicInteger(),denied=new AtomicInteger();try{owner.requestWorkspaceImageSave(ready::incrementAndGet,denied::incrementAndGet);assertEquals(WorkspaceImageSaveAccess.REQUEST,Shadows.shadowOf(owner).getLastRequestedPermission().requestCode);owner.onRequestPermissionsResult(WorkspaceImageSaveAccess.REQUEST,new String[]{Manifest.permission.WRITE_EXTERNAL_STORAGE},new int[]{android.content.pm.PackageManager.PERMISSION_DENIED});assertEquals(0,ready.get());assertEquals(1,denied.get());owner.requestWorkspaceImageSave(ready::incrementAndGet,denied::incrementAndGet);Shadows.shadowOf(RuntimeEnvironment.application).grantPermissions(Manifest.permission.WRITE_EXTERNAL_STORAGE);owner.onRequestPermissionsResult(WorkspaceImageSaveAccess.REQUEST,new String[]{Manifest.permission.WRITE_EXTERNAL_STORAGE},new int[]{android.content.pm.PackageManager.PERMISSION_GRANTED});assertEquals(1,ready.get());owner.onRequestPermissionsResult(WorkspaceImageSaveAccess.REQUEST,new String[]{Manifest.permission.WRITE_EXTERNAL_STORAGE},new int[]{android.content.pm.PackageManager.PERMISSION_GRANTED});assertEquals("A late duplicate cannot save again",1,ready.get());}finally{owner.finish();}}

}
